/* ===== GPS location + zone map ===== */
let rowsG={};
const gmap=(a,b)=>`https://www.google.com/maps?q=${nn(a)},${nn(b)}`;
const okLL=(a,b)=>isFinite(a)&&isFinite(b)&&Math.abs(a)<=90&&Math.abs(b)<=180;
function gPrev(){const a=parseFloat($("gLat").value),b=parseFloat($("gLng").value);$("gPv").innerHTML=okLL(a,b)?`<a href="${gmap(a,b)}" target="_blank" rel="noopener">${esc(t("gOpen"))} ↗</a>`:""}
function fillGps(){if(!cur)return;const d=rowsG[cur[0]];$("gLat").value=d?d.lat:"";$("gLng").value=d?d.lng:"";$("gLnk").value="";gPrev();setM("mG");if(d)setM("mG","wa","already")}
["gLat","gLng"].forEach(i=>$(i).addEventListener("input",gPrev));
$("gLnk").addEventListener("input",()=>{const v=$("gLnk").value,m=v.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/)||v.match(/[?&](?:q|ll|query)=(-?\d+\.\d+)(?:,|%2C)(-?\d+\.\d+)/)||v.match(/!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)/);if(m){$("gLat").value=m[1];$("gLng").value=m[2];gPrev()}});
let gAcc=null;
$("gUse").onclick=()=>{setM("mG","wa","gWait");gAcc=null;if(!navigator.geolocation){setM("mG","er","gFail");return}
navigator.geolocation.getCurrentPosition(p=>{const c=p.coords;$("gLat").value=c.latitude.toFixed(6);$("gLng").value=c.longitude.toFixed(6);gAcc=Math.round(c.accuracy);dirty=true;gPrev();setM("mG","ok","gGot",{a:gAcc})},()=>setM("mG","er","gFail"),{enableHighAccuracy:true,timeout:20000,maximumAge:0})};
$("saveG").onclick=()=>{if(!cur)return;const a=parseFloat($("gLat").value),b=parseFloat($("gLng").value);if(!okLL(a,b)){setM("mG","er","gBad");return}
if(a<5.5||a>10||b<79||b>82.2){setM("mG","er","gOut");return}
saveDoc("locations","mG",{lat:+a.toFixed(6),lng:+b.toFixed(6),acc:gAcc})};
const DC={Badulla:"#3a86ff","Hali-Ela":"#ff5d8f"};
function mapPts(){const dv=$("mgD").value;return S.filter(s=>(!dv||s[3]===dv)&&rowsG[s[0]]).map(s=>({s,g:rowsG[s[0]]}))}
const MP={z:10,lat:6.99,lng:81.05,did:false},mw=z=>256*Math.pow(2,z);
const px=(a,b,z)=>{const r=a*Math.PI/180;return[(b+180)/360*mw(z),(1-Math.log(Math.tan(r)+1/Math.cos(r))/Math.PI)/2*mw(z)]};
const unpx=(x,y,z)=>{const n=Math.PI-2*Math.PI*y/mw(z);return[180/Math.PI*Math.atan(Math.sinh(n)),x/mw(z)*360-180]};
function mapBlk(){$("mgB").classList.remove("hide")}
function mapFit(){const P=mapPts(),B=$("mgS"),w=B.clientWidth,h=B.clientHeight;MP.did=true;if(!P.length){MP.lat=6.99;MP.lng=81.05;MP.z=10;return}
const la=P.map(p=>p.g.lat),lo=P.map(p=>p.g.lng);MP.lat=(Math.min(...la)+Math.max(...la))/2;MP.lng=(Math.min(...lo)+Math.max(...lo))/2;
let z=17;for(;z>6;z--){const a=px(Math.max(...la),Math.min(...lo),z),b=px(Math.min(...la),Math.max(...lo),z);if(b[0]-a[0]<w-70&&b[1]-a[1]<h-70)break}MP.z=z}
function mapRender(){const B=$("mgS"),ml=$("mgL"),w=B.clientWidth,h=B.clientHeight,z=MP.z,n=Math.pow(2,z),[cx,cy]=px(MP.lat,MP.lng,z),ox=cx-w/2,oy=cy-h/2;
ml.style.transform="";ml.innerHTML=mapPts().map(p=>{const[x,y]=px(p.g.lat,p.g.lng,z);return`<i data-c="${p.s[0]}" title="${esc(p.s[1])}" style="position:absolute;left:${Math.round(x-ox-10)}px;top:${Math.round(y-oy-10)}px;width:20px;height:20px;border-radius:50%;background:${DC[p.s[3]]||"#7b5cff"};border:2px solid #fff;box-shadow:0 1px 5px rgba(0,0,0,.55);cursor:pointer"></i>`}).join("");
for(let ty=Math.floor(oy/256);ty<=Math.floor((oy+h)/256);ty++)for(let tx=Math.floor(ox/256);tx<=Math.floor((ox+w)/256);tx++){if(ty<0||ty>=n)continue;
const im=new Image();im.alt="";im.draggable=false;im.onerror=mapBlk;im.src=`https://tile.openstreetmap.org/${z}/${((tx%n)+n)%n}/${ty}.png`;im.style.cssText=`position:absolute;left:${Math.round(tx*256-ox)}px;top:${Math.round(ty*256-oy)}px;width:256px;height:256px;max-width:none`;ml.prepend(im)}}
function drawMap(){if($("pMp").classList.contains("hide"))return;const dv=$("mgD").value,all=S.filter(s=>!dv||s[3]===dv);
$("mgC").textContent=t("mapCnt",{n:mapPts().length,m:all.length});if(!MP.did)mapFit();mapRender();
const mi=all.filter(s=>!rowsG[s[0]]);$("mgMt").textContent=t("mapMis")+" ("+mi.length+")";$("mgM").innerHTML=mi.map(s=>`<div>${s[0]} · ${esc(s[1])}</div>`).join("")}
function mapInfo(c){const s=S.find(x=>String(x[0])===String(c)),g=rowsG[c];if(!s||!g)return;$("mgI").innerHTML=`<p class="name">${s[0]} · ${esc(s[1])}</p><div class="mu" style="margin-bottom:8px">${esc(s[2])} · ${esc(s[3])}<br>${g.lat}, ${g.lng}${g.acc?" (±"+g.acc+" m)":""}</div><a class="btn" style="display:inline-block;text-decoration:none" target="_blank" rel="noopener" href="${gmap(g.lat,g.lng)}">${esc(t("gOpen"))} ↗</a> <a class="btn sec" style="display:inline-block;text-decoration:none" href="#s${s[0]}">${esc(t("mapOpen"))}</a>`}
