(async()=>{try{db=await claude.use("db")}catch(e){}
if(!db){setM("m1","wa","signin");return}
db.collection("locations").onSnapshot(q=>{rowsG={};q.docs.forEach(d=>{const x=d.data()||{},la=+x.lat,lo=+x.lng;if(okLL(la,lo)&&la>=5.5&&la<=10&&lo>=79&&lo<=82.2)rowsG[d.id]={lat:la,lng:lo,acc:nn(x.acc)}});drawMap();if(cur)fillGps();refresh()},e=>{});
db.collection("ict_resources").onSnapshot(q=>{rowsL={};q.docs.forEach(d=>rowsL[d.id]=d.data());refresh()},e=>{});
db.collection("schools").onSnapshot(q=>{rowsS={};q.docs.forEach(d=>rowsS[d.id]=d.data());refresh()},e=>{});
[["teachers","rowsT"],["facilities","rowsF"],["devices","rowsV"]].forEach(([c,v])=>db.collection(c).onSnapshot(q=>{const o={};q.docs.forEach(d=>o[d.id]=d.data());if(v=="rowsT")rowsT=o;else if(v=="rowsF")rowsF=o;else rowsV=o;refresh()},e=>{}))})();
